MOD = 998244353

def countValidHandAssignments(N, P, S):
    def isValidConfiguration(spoon, P, S):
        for p in P:
            if S[p] == 'L':
                if spoon[p] or spoon[(p-1)%N]:
                    spoon[p] = True
                else:
                    return False
            elif S[p] == 'R':
                if spoon[(p+1)%N] or spoon[p]:
                    spoon[(p+1)%N] = True
                else:
                    return False
            elif S[p] == '?':
                if not spoon[p] and not spoon[(p+1)%N]:
                    return False
                if spoon[p]:
                    spoon[(p+1)%N] = True
                else:
                    spoon[p] = True
        return True

    def countConfigurations(S):
        from itertools import product
        count = 0
        for configuration in product('LR', repeat=S.count('?')):
            temp_S = list(S)
            index = 0
            for i in range(N):
                if temp_S[i] == '?':
                    temp_S[i] = configuration[index]
                    index += 1
            spoon = [False] * N
            if isValidConfiguration(spoon, P, temp_S):
                count += 1
        return count

    return countConfigurations(S) % MOD

